package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, m int64
	fmt.Fscan(reader, &n, &m)

	if m == 1 {
		fmt.Fprintln(writer, n-1)
	} else {
		fmt.Fprintln(writer, n*(m-1))
	}
}

