package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	scanner.Scan()
	n := parseInt(scanner.Bytes())
	scanner.Scan()
	m := parseInt(scanner.Bytes())

	var result int64
	if m == 1 {
		result = int64(n - 1)
	} else {
		result = int64(n) * int64(m - 1)
	}

	fmt.Println(result)
}

func parseInt(b []byte) int {
	neg := false
	if len(b) > 0 && b[0] == '-' {
		neg = true
		b = b[1:]
	}
	val := 0
	for _, c := range b {
		val = val*10 + int(c-'0')
	}
	if neg {
		return -val
	}
	return val
}

